contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address oldOwner = c.owner();

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address currentOwner = c.owner();

        assert(
            (msg.sender == oldOwner && !reverted && currentOwner == newOwner) ||
            (msg.sender != oldOwner && reverted && currentOwner == oldOwner)
        );
    }
}

